sources = json.loads("{\"setup_voice_bank.py\": \"\\\"\\\"\\\"Dedicated generator environment; never install into the wakeword/Emily env.\\\"\\\"\\\"\\nfrom pathlib import Path\\nimport hashlib\\nimport os\\nimport shutil\\nimport subprocess\\nimport sys\\n\\n\\ndef run(command,root,env):\\n    with (root/'setup.log').open('a') as log:\\n        with subprocess.Popen([str(x) for x in command],cwd=root,env=env,stdin=subprocess.DEVNULL,\\n                              stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1) as p:\\n            tail=[]\\n            for line in p.stdout:\\n                print(line,end='',flush=True)\\n                log.write(line);log.flush()\\n                tail=(tail+[line])[-25:]\\n            code=p.wait()\\n        if code:\\n            raise RuntimeError(f'Falha na preparação ({code}). Log: {root / \\\"setup.log\\\"}\\\\n'+''.join(tail))\\n\\n\\ndef generator_environment(source):\\n    env = source.copy()\\n    # Keep the NVIDIA driver paths that Colab injects. Only remove known old training libs/stubs.\\n    paths = []\\n    for path in env.get('LD_LIBRARY_PATH','').split(':'):\\n        if not path or '.training-venv/' in path or path.endswith('/stubs'):\\n            continue\\n        paths.append(path)\\n    for path in ['/usr/lib64-nvidia','/usr/local/nvidia/lib64','/usr/local/nvidia/lib']:\\n        if Path(path).is_dir() and path not in paths:\\n            paths.append(path)\\n    if paths:\\n        env['LD_LIBRARY_PATH'] = ':'.join(paths)\\n    else:\\n        env.pop('LD_LIBRARY_PATH',None)\\n    env['OMP_NUM_THREADS']='2';env['OPENBLAS_NUM_THREADS']='2'\\n    env['HF_HUB_DISABLE_TELEMETRY']='1'\\n    return env\\n\\n\\ndef setup(root):\\n    root=Path(root).resolve();root.mkdir(parents=True,exist_ok=True)\\n    env=generator_environment(os.environ)\\n    for executable in ['ffmpeg','sox']:\\n        if not shutil.which(executable):\\n            if not str(root).startswith('/content/'):\\n                raise RuntimeError('Este preparador é para Colab; falta '+executable)\\n            run(['apt-get','update','-qq'],root,env)\\n            run(['apt-get','install','-y','-qq',executable],root,env)\\n    python=root/'.voicegen-venv/bin/python'\\n    if not python.exists():\\n        old=Path('/content/emily-wakeword/.training-venv/bin/python')\\n        if old.is_file():\\n            run([old,'-m','venv',python.parent.parent],root,env)\\n        else:\\n            bootstrap=root/'.bootstrap'\\n            uv=bootstrap/'bin/uv'\\n            if not uv.is_file():\\n                run([sys.executable,'-m','pip','install','--target',bootstrap,'uv==0.8.22'],root,env)\\n            env['UV_PYTHON_INSTALL_DIR']=str(root/'.managed-python')\\n            env['UV_CACHE_DIR']=str(root/'.uv-cache');env['UV_NATIVE_TLS']='true'\\n            run([uv,'venv','--managed-python','--python','3.11','--seed',python.parent.parent],root,env)\\n    if shutil.disk_usage(root).free<20*1024**3:\\n        raise RuntimeError('Menos de 20 GiB livres no Colab. Não iniciar downloads dos modelos.')\\n    signature=hashlib.sha256((root/'requirements-voice-pilot.txt').read_bytes()+b'torch2.6.0+cu124').hexdigest()\\n    ready=root/'.dependencies-ready'\\n    if ready.exists() and ready.read_text()!=signature:\\n        raise RuntimeError('Dependências alteradas; use outra pasta isolada.')\\n    if not ready.exists():\\n        run([python,'-m','pip','install','torch==2.6.0','torchaudio==2.6.0',\\n             '--index-url','https://download.pytorch.org/whl/cu124'],root,env)\\n        run([python,'-m','pip','install','-r',root/'requirements-voice-pilot.txt'],root,env)\\n        run([python,'-m','pip','check'],root,env)\\n        ready.write_text(signature)\\n    run([python,'-m','unittest','test_voice_bank_pilot'],root,env)\\n    try:\\n        run([python,root/'voice_gpu_probe.py'],root,env)\\n    except RuntimeError as error:\\n        raise RuntimeError('A GPU não inicializou no ambiente do gerador. Isso não prova que a T4 '\\n                           'não foi selecionada. O diagnóstico acima identifica driver, visibilidade '\\n                           'e erro real do PyTorch; preserve esta sessão e seus arquivos.') from error\\n    run([python,'-c','from qwen_tts import Qwen3TTSModel; import whisper; '\\n         'print(\\\"Bibliotecas do gerador carregadas.\\\")'],root,env)\\n    return str(python),env\\n\", \"voice_gpu_probe.py\": \"\\\"\\\"\\\"Small GPU probe for a fresh subprocess; prints only GPU-related diagnostics.\\\"\\\"\\\"\\nimport ctypes\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport subprocess\\nimport sys\\n\\ndef probe():\\n    result = dict(python=sys.version.split()[0],executable=sys.executable,\\n                  environment={k:os.environ.get(k) for k in ['CUDA_VISIBLE_DEVICES','NVIDIA_VISIBLE_DEVICES',\\n                    'LD_LIBRARY_PATH','PYTORCH_NVML_BASED_CUDA_CHECK']})\\n    try:\\n        p = subprocess.run(['nvidia-smi','--query-gpu=name,driver_version,memory.total','--format=csv,noheader'],\\n                           capture_output=True,text=True,timeout=15)\\n        result['nvidia_smi']=dict(returncode=p.returncode,stdout=p.stdout.strip(),stderr=p.stderr.strip())\\n    except (OSError,subprocess.TimeoutExpired) as error:\\n        result['nvidia_smi']=dict(error=str(error))\\n    try:\\n        driver=ctypes.CDLL('libcuda.so.1')\\n        driver.cuInit.argtypes=[ctypes.c_uint];driver.cuInit.restype=ctypes.c_int\\n        code=driver.cuInit(0)\\n        result['driver_init_code']=code\\n        name=ctypes.c_char_p()\\n        driver.cuGetErrorName.argtypes=[ctypes.c_int,ctypes.POINTER(ctypes.c_char_p)]\\n        driver.cuGetErrorName(code,ctypes.byref(name))\\n        result['driver_init_name']=name.value.decode() if name.value else None\\n        count=ctypes.c_int()\\n        result['driver_device_count_code']=driver.cuDeviceGetCount(ctypes.byref(count))\\n        result['driver_device_count']=count.value\\n    except (OSError,AttributeError) as error:\\n        result['driver_error']=str(error)\\n    try:\\n        import torch\\n        result.update(torch_version=torch.__version__,torch_cuda_build=torch.version.cuda,\\n                      cuda_available=torch.cuda.is_available())\\n        try:\\n            torch.cuda.init()\\n            result['torch_gpu_name']=torch.cuda.get_device_name(0)\\n            # Initialization alone doesn't verify the CUDA runtime can execute a kernel.\\n            result['kernel_test']=float((torch.ones(4,device='cuda')*2).sum().item())\\n        except Exception as error:\\n            result['torch_init_error']=f'{type(error).__name__}: {error}'\\n    except ImportError as error:\\n        result['torch_import_error']=str(error)\\n    try:\\n        result['loaded_driver_paths']=sorted({line.split()[-1] for line in Path('/proc/self/maps').read_text().splitlines()\\n                                             if 'libcuda.so' in line and line.split()[-1].startswith('/')})\\n    except OSError:\\n        pass\\n    return result\\n\\nif __name__=='__main__':\\n    result=probe()\\n    encoded=json.dumps(result,ensure_ascii=False,indent=2)\\n    Path(__file__).with_name('gpu-diagnostics.json').write_text(encoded)\\n    print(encoded)\\n    raise SystemExit(0 if result.get('kernel_test')==8. else 1)\\n\", \"test_voice_bank_pilot.py\": \"import os\\nimport sys\\nfrom pathlib import Path\\nimport tempfile\\nimport unittest\\nimport numpy as np\\nfrom scipy.io import wavfile\\nfrom setup_voice_bank import run, generator_environment\\nfrom voice_bank_pilot import profiles,transcript_flags,audio_checks,pcm16,read_progress,digest,write_json\\n\\nclass VoiceBankChecks(unittest.TestCase):\\n    def test_count_is_not_inflated_by_repeated_descriptions(self):\\n        rows=profiles(216)\\n        self.assertEqual(len({r['id'] for r in rows}),216)\\n        self.assertEqual(len({r['instruction'] for r in rows}),216)\\n        self.assertEqual(len({r['requested_region'] for r in profiles(12)}),6)\\n    def test_name_alone_and_missing_prefix_not_approved(self):\\n        for text in ['Emily','E Emily','Ei','Emily Ei','Ei Emily abre o YouTube']:\\n            self.assertTrue(transcript_flags(text,True))\\n        self.assertFalse(transcript_flags('Ei, Êmili!',True))\\n        self.assertTrue(transcript_flags('Eu falei ei Emily ontem',False))\\n    def test_invalid_generation_cannot_enter_bank(self):\\n        for audio in [np.zeros(16000),np.full(16000,np.nan),np.ones((2,16000))]:\\n            with self.assertRaises(ValueError):audio_checks(audio,16000)\\n        audio=np.sin(np.arange(3*16000)*.1)*.5\\n        self.assertIn('call_longer_than_v2_training_budget',audio_checks(audio,16000,True)['flags'])\\n    def test_preserve_low_volume_pcm_and_resample_duration(self):\\n        audio=np.sin(np.arange(24000)*.1)*.01\\n        pcm=pcm16(audio,24000)\\n        self.assertEqual(pcm.dtype,np.int16)\\n        self.assertEqual(len(pcm),16000)\\n        self.assertLess(int(np.abs(pcm).max()),500)\\n        self.assertGreater(int(np.abs(pcm).max()),200)\\n    def test_driver_paths_preserved_and_training_libs_removed(self):\\n        original = {'LD_LIBRARY_PATH':'/usr/lib64-nvidia:/content/emily-wakeword/.training-venv/lib/python3.11/site-packages/nvidia/cublas/lib:/usr/local/cuda/lib64/stubs',\\n                    'CUDA_VISIBLE_DEVICES':'0'}\\n        env = generator_environment(original)\\n        self.assertIn('/usr/lib64-nvidia',env['LD_LIBRARY_PATH'].split(':'))\\n        self.assertNotIn('.training-venv/',env['LD_LIBRARY_PATH'])\\n        self.assertNotIn('/stubs',env['LD_LIBRARY_PATH'])\\n        self.assertEqual(env['CUDA_VISIBLE_DEVICES'],'0')\\n        self.assertIn('.training-venv/',original['LD_LIBRARY_PATH'])\\n\\n    def test_setup_failure_reports_real_diagnostics(self):\\n        with tempfile.TemporaryDirectory() as temporary:\\n            root=Path(temporary)\\n            with self.assertRaisesRegex(RuntimeError,'EXPECTED_SETUP_FAILURE'):\\n                run([sys.executable,'-c',\\\"print('EXPECTED_SETUP_FAILURE'); raise SystemExit(7)\\\"],root,os.environ.copy())\\n            self.assertIn('EXPECTED_SETUP_FAILURE',(root/'setup.log').read_text())\\n\\n    def test_resume_rejects_modified_audio_and_changed_bank(self):\\n        with tempfile.TemporaryDirectory() as temporary:\\n            root=Path(temporary)\\n            state=read_progress(root,12)\\n            wavfile.write(root/'a.wav',16000,np.ones(16000,np.int16))\\n            state['records'].append(dict(path='a.wav',sha256=digest(root/'a.wav')))\\n            write_json(root/'progress.json',state)\\n            self.assertEqual(len(read_progress(root,12)['records']),1)\\n            with self.assertRaises(ValueError):read_progress(root,13)\\n            (root/'a.wav').write_bytes(b'changed')\\n            with self.assertRaises(ValueError):read_progress(root,12)\\n\\nif __name__=='__main__':unittest.main()\\n\"}")
